import { WithMockedDate } from "../../../../.storybook/preview";
import { Story, metaBase, Primary } from "./group-admission-storybook-helpers";
import { Meta } from "@storybook/react";
import { expect, within } from "storybook/test";
import { corei18n } from "@/core/labels/i18n";
import { DateHelper } from "@/core/helpers";

const meta = {
  ...metaBase,
  title: "Blocks/Group Admission/Use Fixed Date Step",
} satisfies Meta<WithMockedDate<typeof metaBase.component>>;
export default meta;

const DATE_TO_TEST_TODAY_OPEN = "2025-04-27 17:00:55";
export const UseFixedDateStep: Story = {
  ...Primary,
  args: {
    ...Primary.args,
    stepConfigOverride: {
      ...Primary.args?.stepConfigOverride,
      useFixedDateStep: true,
    },
    mockedDate: new Date(DATE_TO_TEST_TODAY_OPEN),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Wait for 1 seconds to make sure the purchase flow is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    // Expect to see completed icon for fixed date step,
    // step should always be completed regardless of changes to any other steps
    await expect(canvas.getByTestId("FIXED_DATE-step-completed")).toBeVisible();
  },
};

export const ShowOpeningHoursInFixedDateSummary: Story = {
  ...UseFixedDateStep,
  args: {
    ...UseFixedDateStep.args,
    stepConfigOverride: {
      ...UseFixedDateStep.args?.stepConfigOverride,
    },
    showOpeningHoursInFixedDateSummary: true,
  },
};

export const FastTrackExample: Story = {
  ...UseFixedDateStep,
  args: {
    ...ShowOpeningHoursInFixedDateSummary.args,
    stepConfigOverride: {
      ...ShowOpeningHoursInFixedDateSummary.args?.stepConfigOverride,
      hideSelectTimePass: true,
      hideSelectJetPass: true,
      hideUpsell: true,
    },
  },
};

const DATE_TO_TEST_NOT_TODAY_OPEN = "2025-04-28 17:00:55";

export const DateFromURL: Story = {
  ...UseFixedDateStep,
  args: {
    ...FastTrackExample.args,
    urlHashParam: `#date=${DATE_TO_TEST_NOT_TODAY_OPEN}`,
  },
};

const NO_TICKETS_HEADER_TEXT = corei18n.t("fixedDateStepNoTicketsHeader");

const DATE_TO_TEST_TODAY_CLOSED = "2025-04-25 17:00:55";
export const ParkClosedToday: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Wait for 1 seconds to make sure the purchase flow is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    // Expect to see warning that there are no available tickets today
    await expect(canvas.getByText(NO_TICKETS_HEADER_TEXT)).toBeVisible();
    await expect(canvas.getByText(corei18n.t("fixedDateStepNoTicketsInfoToday"))).toBeVisible();
  },
  ...UseFixedDateStep,
  args: {
    ...FastTrackExample.args,
    mockedDate: new Date(DATE_TO_TEST_TODAY_CLOSED),
  },
};

const DATE_TO_TEST_NOT_TODAY_CLOSED = "2025-04-25 17:00:55";
export const ParkClosedDateFromURL: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Wait for 1 seconds to make sure the purchase flow is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    // Expect to see warning that there are no available tickets for the selected date
    await expect(canvas.getByText(NO_TICKETS_HEADER_TEXT)).toBeVisible();
    await expect(
      canvas.getByText(
        corei18n.t("fixedDateStepNoTicketsInfoOtherDay", [
          DateHelper.toStringMMDDWeekday(DATE_TO_TEST_NOT_TODAY_CLOSED),
        ]),
      ),
    ).toBeVisible();
  },
  ...UseFixedDateStep,
  args: {
    ...FastTrackExample.args,
    urlHashParam: `#date=${DATE_TO_TEST_NOT_TODAY_CLOSED}`,
  },
};
